<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sand</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body {
    min-height: 100%;
    background:
      radial-gradient(900px 500px at 50% -10%, #1a1a2c 0%, transparent 55%),
      #09090d;
    color: #e6e4dc;
    font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, sans-serif;
  }
  body {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 14px;
    padding: 24px;
  }
  h1 {
    font-size: 13px;
    letter-spacing: 0.42em;
    font-weight: 600;
    color: #9a97a8;
    text-indent: 0.42em;
  }
  #sand {
    width: 480px;
    height: 480px;
    display: block;
    background: #101018;
    border-radius: 10px;
    box-shadow:
      0 0 0 1px #2c2c3a,
      0 18px 50px rgba(0, 0, 0, 0.55),
      inset 0 0 80px rgba(0, 0, 0, 0.25);
    cursor: crosshair;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    touch-action: none;
  }
  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    justify-content: center;
    max-width: 480px;
  }
  button {
    appearance: none;
    border: 1px solid #3a3a4a;
    background: #17171f;
    color: #eceae3;
    font: 600 12px/1 ui-sans-serif, system-ui, sans-serif;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    padding: 9px 12px;
    border-radius: 8px;
    cursor: pointer;
    user-select: none;
    transition: transform .08s ease, box-shadow .12s ease, border-color .12s ease;
  }
  button:hover { transform: translateY(-1px); }
  button:active { transform: translateY(1px); }
  button.active {
    box-shadow: 0 0 0 2px #0b0b10, 0 0 0 4px var(--accent, #e8c45c);
    border-color: var(--accent, #e8c45c);
  }
  #mat-sand { --accent: #e8c45c; }
  #mat-water { --accent: #3d98e6; }
  #mat-wall { --accent: #8b8d9c; }
  #mat-acid { --accent: #4ae46a; }
  #mat-empty { --accent: #6a6878; }
  #clear {
    background: #2a1518;
    border-color: #6a3038;
    color: #ffb4b8;
    margin-left: 6px;
  }
  .hint {
    font-size: 11px;
    color: #6c6a78;
    letter-spacing: 0.08em;
  }
</style>
</head>
<body>
  <div class="wrap">
    <h1>FALLING SAND</h1>
    <canvas id="sand" width="120" height="120"></canvas>
    <div class="controls">
      <button id="mat-sand" class="active">Sand</button>
      <button id="mat-water">Water</button>
      <button id="mat-wall">Wall</button>
      <button id="mat-acid">Acid</button>
      <button id="mat-empty">Erase</button>
      <button id="clear">Clear</button>
    </div>
    <div class="hint">drag to paint · liquids yield around denser sand</div>
  </div>
<script>
(function () {
  const W = 120;
  const H = 120;
  const EMPTY = 0, SAND = 1, WATER = 2, WALL = 3, ACID = 4;
  const NAME = ['empty', 'sand', 'water', 'wall', 'acid'];
  const ID = { empty: 0, sand: 1, water: 2, wall: 3, acid: 4 };

  const COL = [
    [16, 16, 24],
    [232, 196, 88],
    [48, 150, 228],
    [96, 98, 116],
    [72, 230, 108]
  ];

  const grid = new Uint8Array(W * H);
  const canvas = document.getElementById('sand');
  const ctx = canvas.getContext('2d', { alpha: false });
  const img = ctx.createImageData(W, H);
  const pix = img.data;

  let selected = SAND;
  let painting = false;
  let lastX = -1, lastY = -1;

  const idx = (x, y) => y * W + x;
  const inb = (x, y) => x >= 0 && x < W && y >= 0 && y < H;

  function clearGrid() {
    grid.fill(EMPTY);
  }

  function paintCell(x, y, mat) {
    if (inb(x, y)) grid[idx(x, y)] = mat;
  }

  function brush(cx, cy, mat) {
    const r = mat === WALL ? 1 : (mat === EMPTY ? 2 : 2);
    const r2 = r * r + (mat === WALL ? 0 : 1);
    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        if (dx * dx + dy * dy <= r2) paintCell(cx + dx, cy + dy, mat);
      }
    }
  }

  function stroke(x0, y0, x1, y1, mat) {
    let dx = Math.abs(x1 - x0), dy = Math.abs(y1 - y0);
    const sx = x0 < x1 ? 1 : -1;
    const sy = y0 < y1 ? 1 : -1;
    let err = dx - dy;
    for (;;) {
      brush(x0, y0, mat);
      if (x0 === x1 && y0 === y1) break;
      const e2 = 2 * err;
      if (e2 > -dy) { err -= dy; x0 += sx; }
      if (e2 < dx) { err += dx; y0 += sy; }
    }
  }

  function eventCell(e) {
    const r = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - r.left) / r.width * W);
    const y = Math.floor((e.clientY - r.top) / r.height * H);
    return [x, y];
  }

  function isLiquid(v) { return v === WATER || v === ACID; }

  function step() {
    const moved = new Uint8Array(W * H);

    function moveInto(x, y, nx, ny) {
      const a = idx(x, y), b = idx(nx, ny);
      grid[b] = grid[a];
      grid[a] = EMPTY;
      moved[b] = 1;
    }

    function swapCells(x, y, nx, ny) {
      const a = idx(x, y), b = idx(nx, ny);
      const t = grid[a];
      grid[a] = grid[b];
      grid[b] = t;
      moved[a] = 1;
      moved[b] = 1;
    }

    function displaceLiquid(x, y, nx, ny) {
      const order = Math.random() < 0.5 ? [-1, 1] : [1, -1];
      for (let k = 0; k < 2; k++) {
        const sx = nx + order[k];
        if (inb(sx, ny) && !moved[idx(sx, ny)] && grid[idx(sx, ny)] === EMPTY) {
          grid[idx(sx, ny)] = grid[idx(nx, ny)];
          grid[idx(nx, ny)] = grid[idx(x, y)];
          grid[idx(x, y)] = EMPTY;
          moved[idx(sx, ny)] = 1;
          moved[idx(nx, ny)] = 1;
          return;
        }
      }
      for (let k = 0; k < 2; k++) {
        const sx = x + order[k];
        if (inb(sx, y) && !moved[idx(sx, y)] && grid[idx(sx, y)] === EMPTY) {
          grid[idx(sx, y)] = grid[idx(nx, ny)];
          grid[idx(nx, ny)] = grid[idx(x, y)];
          grid[idx(x, y)] = EMPTY;
          moved[idx(sx, y)] = 1;
          moved[idx(nx, ny)] = 1;
          return;
        }
      }
      swapCells(x, y, nx, ny);
    }

    function trySand(x, y, nx, ny) {
      if (!inb(nx, ny) || moved[idx(nx, ny)]) return false;
      const t = grid[idx(nx, ny)];
      if (t === EMPTY) { moveInto(x, y, nx, ny); return true; }
      if (isLiquid(t)) { displaceLiquid(x, y, nx, ny); return true; }
      return false;
    }

    function tryEmpty(x, y, nx, ny) {
      if (!inb(nx, ny) || moved[idx(nx, ny)]) return false;
      if (grid[idx(nx, ny)] !== EMPTY) return false;
      moveInto(x, y, nx, ny);
      return true;
    }

    function fallFluid(x, y) {
      const d1 = Math.random() < 0.5 ? -1 : 1;
      if (tryEmpty(x, y, x, y + 1)) return true;
      if (tryEmpty(x, y, x + d1, y + 1)) return true;
      if (tryEmpty(x, y, x - d1, y + 1)) return true;
      return false;
    }

    function spreadFluid(x, y) {
      const d1 = Math.random() < 0.5 ? -1 : 1;
      if (tryEmpty(x, y, x + d1, y)) return true;
      if (tryEmpty(x, y, x - d1, y)) return true;
      return false;
    }

    function dissolveFrom(x, y) {
      const dirs = [[0, 1], [-1, 0], [1, 0]];
      if (Math.random() < 0.5) {
        const tmp = dirs[1]; dirs[1] = dirs[2]; dirs[2] = tmp;
      }
      for (let i = 0; i < dirs.length; i++) {
        const nx = x + dirs[i][0], ny = y + dirs[i][1];
        if (!inb(nx, ny) || moved[idx(nx, ny)]) continue;
        const t = grid[idx(nx, ny)];
        if (t === SAND || t === WALL) {
          grid[idx(nx, ny)] = EMPTY;
          moved[idx(nx, ny)] = 1;
          return;
        }
      }
    }

    for (let y = H - 1; y >= 0; y--) {
      const ltr = (y & 1) === 0;
      for (let i = 0; i < W; i++) {
        const x = ltr ? i : W - 1 - i;
        const p = idx(x, y);
        if (moved[p]) continue;
        const m = grid[p];
        if (m === EMPTY || m === WALL) continue;

        if (m === SAND) {
          const d1 = Math.random() < 0.5 ? -1 : 1;
          if (trySand(x, y, x, y + 1)) continue;
          if (trySand(x, y, x + d1, y + 1)) continue;
          trySand(x, y, x - d1, y + 1);
        } else if (m === WATER) {
          if (fallFluid(x, y)) continue;
          spreadFluid(x, y);
        } else if (m === ACID) {
          dissolveFrom(x, y);
          if (moved[p] || grid[p] !== ACID) continue;
          if (fallFluid(x, y)) continue;
          spreadFluid(x, y);
        }
      }
    }
  }

  function render() {
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const m = grid[idx(x, y)];
        const c = COL[m];
        const n = ((x * 157 + y * 313) & 7) - 3;
        const o = (y * W + x) * 4;
        const j = (m === EMPTY) ? 0 : n * (m === WATER || m === ACID ? 2 : 4);
        pix[o]     = Math.max(0, Math.min(255, c[0] + j));
        pix[o + 1] = Math.max(0, Math.min(255, c[1] + j));
        pix[o + 2] = Math.max(0, Math.min(255, c[2] + j));
        pix[o + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
  }

  function tick(n) {
    n = n | 0;
    for (let i = 0; i < n; i++) step();
    render();
  }

  function get(x, y) {
    if (!inb(x, y)) return 'empty';
    return NAME[grid[idx(x, y)]];
  }

  function set(x, y, material) {
    if (!inb(x, y)) return;
    const id = ID[material];
    if (id === undefined) return;
    grid[idx(x, y)] = id;
    render();
  }

  function clearAll() {
    clearGrid();
    render();
  }

  window.sim = {
    w: W,
    h: H,
    tick: tick,
    get: get,
    set: set,
    clear: clearAll
  };

  const buttons = {
    sand: document.getElementById('mat-sand'),
    water: document.getElementById('mat-water'),
    wall: document.getElementById('mat-wall'),
    acid: document.getElementById('mat-acid'),
    empty: document.getElementById('mat-empty')
  };
  const matOf = { sand: SAND, water: WATER, wall: WALL, acid: ACID, empty: EMPTY };

  function selectMat(name) {
    selected = matOf[name];
    Object.keys(buttons).forEach(function (k) {
      buttons[k].classList.toggle('active', k === name);
    });
  }

  buttons.sand.addEventListener('click', function () { selectMat('sand'); });
  buttons.water.addEventListener('click', function () { selectMat('water'); });
  buttons.wall.addEventListener('click', function () { selectMat('wall'); });
  buttons.acid.addEventListener('click', function () { selectMat('acid'); });
  buttons.empty.addEventListener('click', function () { selectMat('empty'); });
  document.getElementById('clear').addEventListener('click', clearAll);

  canvas.addEventListener('pointerdown', function (e) {
    e.preventDefault();
    canvas.setPointerCapture(e.pointerId);
    painting = true;
    const c = eventCell(e);
    lastX = c[0]; lastY = c[1];
    brush(c[0], c[1], selected);
    render();
  });
  canvas.addEventListener('pointermove', function (e) {
    if (!painting) return;
    const c = eventCell(e);
    stroke(lastX, lastY, c[0], c[1], selected);
    lastX = c[0]; lastY = c[1];
    render();
  });
  function endPaint(e) {
    painting = false;
    try { canvas.releasePointerCapture(e.pointerId); } catch (err) {}
  }
  canvas.addEventListener('pointerup', endPaint);
  canvas.addEventListener('pointercancel', endPaint);

  render();
  function loop() {
    step();
    render();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
